#define CPU_BENCH_NO_MAIN
#include "cpu_bench.cpp"
#include "../common/dataset_cache.hpp"
int main(int argc,char**argv){try{
 if(argc==2&&std::string(argv[1])=="--self-test"){selftest();return 0;}
 require(argc==7,"usage: tiled_cpu FIXTURE NEW_RESULTS REPS WARMUPS THREADS save|nosave");fs::path root=argv[1],dir=argv[2];require(!fs::exists(dir),"result exists");auto session_entry=Clock::now();CachedDataset cache(root);auto loaded_once=Clock::now();unsigned reps=count(argv[3],100),warm=count(argv[4],10),threads=count(argv[5],2);require(reps>0&&(threads==1||threads==2),"repetitions/threads");bool save=std::string(argv[6])=="save";require(save||std::string(argv[6])=="nosave","save flag");
 fs::create_directories(dir/"outputs");InputCase in;std::vector<uint64_t> out(cache.chunks.front().expected.size());ComputePool pool(in,out,threads);auto ready=Clock::now();
 std::ofstream setup(dir/"setup.json");setup<<std::setprecision(12)<<"{\"dataset_load_ms\":"<<elapsed(session_entry,loaded_once)<<",\"buffer_pool_setup_ms\":"<<elapsed(loaded_once,ready)<<",\"setup_ms\":"<<elapsed(session_entry,ready)<<",\"input_bytes\":"<<cache.input_bytes<<",\"golden_bytes\":"<<cache.golden_bytes<<",\"ordinary_host_ram\":true}\n";setup.close();require(bool(setup),"setup write");
 std::ofstream csv(dir/"chunks.csv"),whole(dir/"iterations.csv");csv<<std::fixed<<std::setprecision(6);whole<<std::fixed<<std::setprecision(6);csv<<"repetition,warmup,chunk,cache_select_poison_ms,compute_ms,validation_ms,verified_call_ms,output_save_ms,verified_words\n";whole<<"repetition,warmup,compute_sum_ms,verified_call_sum_ms,full_replay_ms\n";
 std::vector<double> computes,calls,fulls;
 for(unsigned rep=0;rep<reps+warm;++rep){auto fullbegin=Clock::now();double sum=0,call=0;bool iswarm=rep<warm;
  for(auto& chunk:cache.chunks){const auto& c=chunk.spec;auto begin=Clock::now();CachedInputLease lease(in,chunk.input);const auto& expected=chunk.expected;std::fill(out.begin(),out.end(),UINT64_MAX);auto loaded=Clock::now();pool.run();auto computed=Clock::now();compare(out,expected);lease.restore();auto checked=Clock::now();if(save&&rep+1==reps+warm)save_output(dir/"outputs"/(c.id+"_output.bin"),chunk.input,out);auto saved=Clock::now();double cm=elapsed(loaded,computed),tx=elapsed(begin,checked);sum+=cm;call+=tx;csv<<rep<<','<<iswarm<<','<<c.id<<','<<elapsed(begin,loaded)<<','<<cm<<','<<elapsed(computed,checked)<<','<<tx<<','<<elapsed(checked,saved)<<','<<out.size()<<'\n';require(bool(csv),"CSV write");}
  double full=elapsed(fullbegin,Clock::now());whole<<rep<<','<<iswarm<<','<<sum<<','<<call<<','<<full<<'\n';require(bool(whole),"CSV write");if(!iswarm){computes.push_back(sum);calls.push_back(call);fulls.push_back(full);}std::cout<<"PASS CACHED_CPU_REPLAY repetition="<<rep<<" warmup="<<iswarm<<" compute_sum_ms="<<sum<<" full_replay_ms="<<full<<'\n'<<std::flush;
 }
 std::ofstream f(dir/"summary.json");f<<std::setprecision(12)<<"{\"status\":\"PASS_FULL_RAW_MAC_CPU_REPLAY\",\"threads\":"<<threads<<",\"chunks\":"<<cache.chunks.size()<<",\"measured\":"<<reps<<",\"warmups\":"<<warm<<",\"compute_sum_median_ms\":"<<med(computes)<<",\"chunk_verified_call_sum_median_ms\":"<<med(calls)<<",\"full_replay_median_ms\":"<<med(fulls)<<",\"scope\":\"u128 accumulation with modulo after each sum; persistent 1/2 compute threads; cached steady state excludes one-time admission (reported in setup.json); includes poison and full integer checks; not OpenFHE or optimal-CPU claim\"}\n";require(bool(f),"summary write");return 0;
}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
